-- ============================================================================
-- 011_fix_enem_2025_ranking_porte.sql
-- Correcoes de qualidade ENEM 2025 (espelha a limpeza feita no CSV consolidado do ML):
--   (1) RANKING UNICO: o ETL gerava empates (rank method=min) para 2025, inconsistente
--       com 2018-2024 (ranking unico). Reordena 2025 para ROW_NUMBER deterministico
--       (media_geral DESC, codigo_inep ASC), igual a recalculate_rankings corrigido.
--   (2) PORTE: backfill via Censo Escolar 2025 (concluintes do Novo Ensino Medio,
--       todos os itinerarios). Origem: scripts/build_censo_escolas_2025.py.
-- Idempotente. Afeta apenas ano=2025.
-- ============================================================================
BEGIN;

-- (1) Ranking unico 2025 -------------------------------------------------------
WITH ranked AS (
  SELECT codigo_inep, ano,
         ROW_NUMBER() OVER (ORDER BY media_geral DESC, codigo_inep)                              AS rk_nac,
         ROW_NUMBER() OVER (PARTITION BY uf ORDER BY media_geral DESC, codigo_inep)              AS rk_uf,
         ROW_NUMBER() OVER (PARTITION BY uf, municipio ORDER BY media_geral DESC, codigo_inep)   AS rk_mun
  FROM public.enem_results
  WHERE ano = 2025 AND media_geral IS NOT NULL
)
UPDATE public.enem_results e
SET ranking_nacional  = r.rk_nac,
    ranking_uf        = r.rk_uf,
    ranking_municipio = r.rk_mun,
    updated_at        = NOW()
FROM ranked r
WHERE e.codigo_inep = r.codigo_inep AND e.ano = r.ano
  AND (e.ranking_nacional IS DISTINCT FROM r.rk_nac
    OR e.ranking_uf IS DISTINCT FROM r.rk_uf
    OR e.ranking_municipio IS DISTINCT FROM r.rk_mun);

