  ('53048008', 2, 'Pequena (31-100)'),
  ('53051009', 3, 'Média (101-200)'),
  ('53056000', 3, 'Média (101-200)'),
  ('53068068', 3, 'Média (101-200)'),
  ('53068092', 4, 'Grande (201-400)'),
  ('53068181', 4, 'Grande (201-400)'),
  ('53082001', 1, 'Muito pequena (até 30)'),
  ('53086007', 2, 'Pequena (31-100)')
)
UPDATE public.enem_results e
SET porte       = p.porte,
    porte_label = p.porte_label,
    updated_at  = NOW()
FROM porte_2025 p
WHERE e.codigo_inep = p.codigo_inep AND e.ano = 2025
  AND (e.porte IS DISTINCT FROM p.porte OR e.porte_label IS DISTINCT FROM p.porte_label);

COMMIT;

